#include <map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    map<long long, int> count;
    for (int i = 0; i < n; i++) count[a[i]]++;
    bool any = false;
    for (auto& entry : count) {
        if (entry.second >= 2) {
            if (any) cout << " ";
            cout << entry.first;
            any = true;
        }
    }
    cout << (any ? "" : "none") << "\n";

    return 0;
}

